<template>
	<uv-navbar 
		:title="title"
		:bgColor="bgColor"
		:leftIcon="leftIcon"
		:leftText="leftText"
		:rightText="rightText"
		:rightIcon="rightIcon"
		:leftIconSize="leftIconSize"
		:leftIconColor="leftIconColor"
		:titleStyle="titleStyle"
		:height="height"
		:autoBack="autoBack"
		:fixed="fixed"
		:safeAreaInsetTop="safeAreaInsetTop"
		:placeholder="placeholder"
		:border="border"
		@leftClick="handleLeftClick"
		@rightClick="handleRightClick"
	>
		<!-- 自定义左侧内容插槽 -->
		<template v-if="$slots.left" #left>
			<slot name="left"></slot>
		</template>
		
		<!-- 自定义中间内容插槽 -->
		<template v-if="$slots.center" #center>
			<slot name="center"></slot>
		</template>
		
		<!-- 自定义右侧内容插槽 -->
		<template v-if="$slots.right" #right>
			<slot name="right"></slot>
		</template>
	</uv-navbar>
</template>

<script>
export default {
	name: 'CustomNavbar',
	props: {
		// 导航栏标题
		title: {
			type: String,
			default: ''
		},
		// 背景颜色
		bgColor: {
			type: String,
			default: '#1890FF'
		},
		// 左边返回图标的名称
		leftIcon: {
			type: String,
			default: 'arrow-left'
		},
		// 左边的提示文字
		leftText: {
			type: String,
			default: ''
		},
		// 右边的提示文字
		rightText: {
			type: String,
			default: ''
		},
		// 右边返回图标的名称
		rightIcon: {
			type: String,
			default: ''
		},
		// 左侧返回图标的大小
		leftIconSize: {
			type: [String, Number],
			default: 20
		},
		// 左侧返回图标的颜色
		leftIconColor: {
			type: String,
			default: '#ffffff'
		},
		// 标题的样式
		titleStyle: {
			type: [String, Object],
			default: () => ({
				color: '#ffffff',
				fontSize: '18px',
				fontWeight: 'bold'
			})
		},
		// 导航栏高度(不包括状态栏高度在内)
		height: {
			type: [String, Number],
			default: 44
		},
		// 点击左侧区域(返回图标)，是否自动返回上一页
		autoBack: {
			type: Boolean,
			default: true
		},
		// 导航栏是否固定在顶部
		fixed: {
			type: Boolean,
			default: true
		},
		// 是否开启顶部安全区适配
		safeAreaInsetTop: {
			type: Boolean,
			default: true
		},
		// 固定在顶部时，是否生成一个等高元素，以防止塌陷
		placeholder: {
			type: Boolean,
			default: true
		},
		// 导航栏底部是否显示下边框
		border: {
			type: Boolean,
			default: false
		}
	},
	methods: {
		// 处理左侧点击事件
		handleLeftClick() {
			this.$emit('leftClick');
		},
		
		// 处理右侧点击事件
		handleRightClick() {
			this.$emit('rightClick');
		}
	}
}
</script>

<style scoped>
/* 使用 uv-ui 官方组件的样式，无需额外样式 */
</style>
